#include "Audio/Mastering.h"
#include "Audio/OfflineAudio.h"
#include "Session/Session.h"
#include <iostream>
#include <cmath>
#include <new>
#include <cstdlib>
namespace {thread_local bool probe=false;int allocations=0,checks=0;}
void* operator new(size_t n){if(probe)++allocations;if(auto* p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void operator delete(void* p)noexcept{std::free(p);}void operator delete(void* p,size_t)noexcept{std::free(p);}
namespace {
void expect(bool ok,const char* label){if(!ok)throw std::runtime_error(label);++checks;std::cout<<"PASS: "<<label<<'\n';}
void feed(nova::MasteringMeter& meter,double rate,float amplitude,double seconds=1,double frequency=997,double phase=0,bool reset=true){meter.prepare(rate);if(reset)meter.reset();juce::AudioBuffer<float> input(2,256);const int frames=int(rate*seconds);for(int offset=0;offset<frames;offset+=256){const int size=std::min(256,frames-offset);for(int c=0;c<2;++c)for(int n=0;n<size;++n)input.setSample(c,n,amplitude*float(std::sin(2*juce::MathConstants<double>::pi*frequency*(offset+n)/rate+phase)));probe=true;meter.process(input.getArrayOfReadPointers(),2,size);probe=false;meter.service();}meter.finishTruePeak();meter.service();}
std::unique_ptr<juce::AudioFormatReader> read(const juce::File& file){juce::WavAudioFormat format;return std::unique_ptr<juce::AudioFormatReader>(format.createReaderFor(file.createInputStream().release(),true));}
}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI gui;try{expect(argc>=2,"mastering fixture directory supplied");juce::File folder(juce::String::fromUTF8(argv[1]));folder.createDirectory();const auto dir=folder.getChildFile(juce::Uuid().toString());dir.createDirectory();juce::String error;
    if(argc>=3&&juce::String(argv[2])=="benchmark"){juce::AudioBuffer<float> input(2,480);for(int c=0;c<2;++c)for(int n=0;n<480;++n)input.setSample(c,n,0.1f*float(std::sin(2*juce::MathConstants<double>::pi*997*n/48000)));for(int pass=0;pass<3;++pass){nova::MasteringMeter measured;int64_t ticks=0;for(int block=0;block<1000;++block){const auto before=juce::Time::getHighResolutionTicks();measured.process(input.getArrayOfReadPointers(),2,480);ticks+=juce::Time::getHighResolutionTicks()-before;measured.service();}std::cout<<"METER BENCHMARK: pass="<<pass<<" frames=480000 meanCallbackUs="<<juce::Time::highResolutionTicksToSeconds(ticks)*1000<<'\n';}}
    nova::MasteringMeter meter;for(double rate:{44100.0,48000.0,96000.0}){feed(meter,rate,0.1f);std::cout<<"LUFS @"<<rate<<"="<<meter.integrated()<<'\n';expect(std::abs(meter.integrated()+20)<0.12&&std::abs(meter.momentary()+20)<0.12,"K-weighted integrated and momentary loudness match stereo 997 Hz reference across sample rates");}
    expect(std::abs(meter.crest()-3.01)<0.1,"dynamic crest factor distinguishes sine RMS from peak");const auto peakBin=std::max_element(meter.spectrum().begin(),meter.spectrum().end())-meter.spectrum().begin();expect(std::abs(peakBin*96000.0/2048-997)<60,"FFT spectrum identifies the actual reference tone");
    feed(meter,48000,1,1,12000,juce::MathConstants<double>::pi/4);expect(std::abs(meter.truePeak())<0.15,"4x FIR true peak detects inter-sample full-scale peak when sample peaks are minus three dB");
    feed(meter,48000,0.1f,2);feed(meter,48000,0.001f,2,997,0,false);expect(std::abs(meter.integrated()+20)<0.6,"relative loudness gate excludes quiet programme blocks instead of averaging their silence");
    feed(meter,48000,0);expect(!std::isfinite(meter.integrated())&&!std::isfinite(meter.momentary()),"silence has no finite LUFS and does not invent a normalization gain");
    uint64_t random=1234567;double mean=0,square=0;constexpr int draws=100000;const double lsb=1.0/32768;for(int n=0;n<draws;++n){const double noise=nova::MasteringExport::ditherSample(0,16,random);mean+=noise;square+=noise*noise;}expect(std::abs(mean/draws)<lsb*0.01&&std::abs(std::sqrt(square/draws)/lsb-std::sqrt(1.0/6))<0.01,"TPDF dither has near-zero DC and expected one-LSB triangular distribution");expect(nova::MasteringExport::ditherSample(0.123f,32,random)==0.123f,"float32 export does not add integer dither");
    const auto source=dir.getChildFile("original.wav");juce::AudioBuffer<float> signal(2,96000);for(int c=0;c<2;++c)for(int n=0;n<96000;++n)signal.setSample(c,n,0.1f*float(std::sin(2*juce::MathConstants<double>::pi*997*n/48000)));{juce::WavAudioFormat format;std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(source.createOutputStream().release(),48000,2,24,{},0));expect(writer&&writer->writeFromAudioSampleBuffer(signal,0,96000),"write real mastering audio fixture");}
    juce::MemoryBlock original;source.loadFileAsData(original);nova::AudioEngine engine;engine.setOutputRate(48000);engine.setSmoothingTime(0);engine.addClip(nova::AudioEngine::loadWav(source,error),error);engine.masteringEnabled=true;engine.play();juce::AudioBuffer<float> output(2,256);for(int n=0;n<400;++n){probe=true;engine.render(output.getArrayOfWritePointers(),2,256);probe=false;engine.mastering->service();}expect(std::abs(engine.mastering->integrated()+20)<0.15,"enabled live Master meter measures actual engine output");engine.stop();engine.masteringEnabled=false;
    for(int bits:{16,24,32}){nova::ExportOptions options;options.bits=bits;options.sampleRate=bits==16?44100:bits==24?48000:96000;options.normalize=true;options.targetLufs=-14;auto offline=nova::OfflineAudio::snapshot(engine,dir,error);expect(bool(offline),"prepare independent snapshot for mastered export");offline->setOutputRate(options.sampleRate);nova::ExportResult result;const auto file=dir.getChildFile("master-"+juce::String(bits)+".wav");expect(nova::MasteringExport::mix(*offline,0,2,file,options,result,error),"export normalized actual WAV outside callback");auto reader=read(file);expect(reader&&reader->bitsPerSample==bits&&reader->sampleRate==options.sampleRate&&reader->lengthInSamples==int64_t(options.sampleRate*2)&&reader->usesFloatingPointData==(bits==32),"export WAV has requested PCM16 PCM24 or float32 format sample rate and exact frame count");nova::MasteringMeter verified;verified.prepare(options.sampleRate);juce::AudioBuffer<float> block(2,4096);for(int64_t pos=0;pos<reader->lengthInSamples;pos+=4096){int size=int(std::min<int64_t>(4096,reader->lengthInSamples-pos));reader->read(&block,0,size,pos,true,true);verified.process(block.getArrayOfReadPointers(),2,size);verified.service();}verified.finishTruePeak();expect(std::abs(verified.integrated()+14)<0.15&&verified.truePeak()<=options.ceilingDbTP+0.05,"decoded exported samples reach target loudness and obey true-peak ceiling");expect(!nova::MasteringExport::mix(*offline,0,2,file,options,result,error),"mastering never overwrites an existing file");}
    nova::ExportOptions limited;limited.bits=32;limited.normalize=true;limited.targetLufs=-5;limited.ceilingDbTP=-12;auto limitedEngine=nova::OfflineAudio::snapshot(engine,dir,error);nova::ExportResult limitedResult;expect(nova::MasteringExport::mix(*limitedEngine,0,2,dir.getChildFile("limited.wav"),limited,limitedResult,error)&&limitedResult.achievedLufs<-11.9&&limitedResult.truePeakDb+limitedResult.gainDb<=-12+1e-6,"normalization reports achievable loudness when true-peak ceiling prevents requested target");
    engine.addClip(nova::AudioEngine::loadWav(source,error),error);engine.track(1).gain=0.5f;auto stemsEngine=nova::OfflineAudio::snapshot(engine,dir,error);nova::ExportOptions stemOptions;stemOptions.bits=32;std::vector<nova::ExportResult> stems;expect(nova::MasteringExport::stems(*stemsEngine,0,2,dir.getChildFile("stems"),stemOptions,stems,error)&&stems.size()==2,"export independent audio stems through mixer routing and Master");auto a=read(stems[0].file),b=read(stems[1].file);juce::AudioBuffer<float> left(2,1024),right(2,1024);a->read(&left,0,1024,0,true,true);b->read(&right,0,1024,0,true,true);expect(std::abs(right.getSample(0,500)-left.getSample(0,500)*0.5f)<1e-5f,"isolated stems preserve independent source gains without summing other sources");
    engine.exportOptions={44100,-16,-2,16,true,true};const auto session=dir.getChildFile("mastering.novadaw");nova::AudioEngine loaded;loaded.setOutputRate(48000);expect(nova::Session::save(session,engine,error)&&nova::Session::load(session,loaded,error)&&loaded.exportOptions.bits==16&&loaded.exportOptions.sampleRate==44100&&loaded.exportOptions.targetLufs==-16&&loaded.exportOptions.normalize,"export and normalization settings survive session roundtrip");
    std::atomic<bool> cancel{true};const auto cancelled=dir.getChildFile("cancelled.wav");expect(!nova::MasteringExport::mix(*stemsEngine,0,2,cancelled,stemOptions,limitedResult,error,&cancel)&&!cancelled.existsAsFile(),"cancelled mastering leaves no published partial destination");juce::MemoryBlock after;source.loadFileAsData(after);expect(after==original,"mastering normalization dither and stems preserve original WAV byte-for-byte");expect(allocations==0,"live loudness true-peak and spectrum capture have no observed C++ allocations in render");
    std::cout<<checks<<" mastering checks passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
